# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">GERUNDS (-ING) AND INFINITIVES (TO + V1) IN THEME 2</text>\n  <rect x="25" y="50" width="205" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="127" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Gerunds (Verb + -ing)</text>\n  <text x="40" y="102" font-size="10.5" fill="#334155">• After Prepositions:</text>\n  <text x="48" y="118" font-size="10" fill="#475569">keen on, fond of, good at,</text>\n  <text x="48" y="133" font-size="10" fill="#475569">interested in, crazy about + V-ing</text>\n  <text x="40" y="156" font-size="10.5" fill="#334155">• After Specific Verbs:</text>\n  <text x="48" y="172" font-size="10" fill="#475569">enjoy, avoid, mind, suggest,</text>\n  <text x="48" y="187" font-size="10" fill="#475569">practise, finish, give up + V-ing</text>\n  <rect x="247" y="50" width="205" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Full Infinitives (to + V1)</text>\n  <text x="262" y="102" font-size="10.5" fill="#334155">• After Specific Verbs:</text>\n  <text x="270" y="118" font-size="10" fill="#475569">want, decide, hope, plan, promise,</text>\n  <text x="270" y="133" font-size="10" fill="#475569">manage, refuse, afford + to V1</text>\n  <text x="262" y="156" font-size="10.5" fill="#334155">• After Adjectives &amp; Purpose:</text>\n  <text x="270" y="172" font-size="10" fill="#475569">happy to help, easy to learn,</text>\n  <text x="270" y="187" font-size="10" fill="#475569">would like / would love + to V1</text>\n  <rect x="470" y="50" width="205" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="572" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Bare Infinitive (V1)</text>\n  <text x="485" y="102" font-size="10.5" fill="#334155">• After Modals:</text>\n  <text x="493" y="118" font-size="10" fill="#475569">can, could, should, must + V1</text>\n  <text x="485" y="142" font-size="10.5" fill="#334155">• With Would Rather:</text>\n  <text x="493" y="158" font-size="10" font-weight="bold" fill="#854d0e">would rather + V1 + than + V1</text>\n  <text x="485" y="182" font-size="10.5" fill="#334155">• After Let / Make:</text>\n  <text x="493" y="198" font-size="10" fill="#475569">make someone V1 / let someone V1</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PAST VS. PRESENT TALENTS &amp; ACHIEVEMENT STORIES</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">General Past Ability: COULD</text>\n  <text x="50" y="105" font-size="11" fill="#334155">• Used for general skills and talents</text>\n  <text x="60" y="122" font-size="10.5" fill="#475569">in the past (repeated / natural ability):</text>\n  <text x="50" y="148" font-size="10.5" font-weight="bold" fill="#1e40af">&quot;Mozart could play the piano ve compose</text>\n  <text x="50" y="165" font-size="10.5" font-weight="bold" fill="#1e40af">music when he was only beş years old.&quot;</text>\n  <text x="50" y="195" font-size="10.5" fill="#334155">• Negative: couldn\'t + V1 (both general</text>\n  <text x="60" y="212" font-size="10.5" fill="#475569">and specific past inability).</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Specific Achievement: WAS/WERE ABLE TO</text>\n  <text x="380" y="105" font-size="11" fill="#334155">• Used for overcoming a difficulty on</text>\n  <text x="390" y="122" font-size="10.5" fill="#475569">one specific occasion (= managed to):</text>\n  <text x="380" y="148" font-size="10.5" font-weight="bold" fill="#991b1b">&quot;Despite her injury, the athlete was able to</text>\n  <text x="380" y="165" font-size="10.5" font-weight="bold" fill="#991b1b">(managed to) win the gold medal yesterday.&quot;</text>\n  <text x="380" y="195" font-size="10.5" fill="#334155">• Key words: finally, in the end, despite,</text>\n  <text x="390" y="212" font-size="10.5" fill="#475569">after hours of effort.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">THEME 2 REVISION: VOCABULARY &amp; BIOGRAPHY WRITING</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Key Vocabulary: Talents &amp; Success</text>\n  <text x="50" y="103" font-size="11" fill="#334155">• gifted / talented: üstün yetenekli</text>\n  <text x="50" y="123" font-size="11" fill="#334155">• pursue a dream: hayalinin peşinden gitmek</text>\n  <text x="50" y="143" font-size="11" fill="#334155">• overcome obstacles: engelleri aşmak</text>\n  <text x="50" y="163" font-size="11" fill="#334155">• determination / dedication: kararlılık</text>\n  <text x="50" y="183" font-size="11" fill="#334155">• excel in / master: bir alanda ustalaşmak</text>\n  <text x="50" y="203" font-size="11" fill="#334155">• inspiring / remarkable: ilham verici</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Structuring an Achievement Story</text>\n  <text x="380" y="103" font-size="11" fill="#334155">1. Introduction: Introduce the person and</text>\n  <text x="392" y="120" font-size="10.5" fill="#475569">their early interest/talent (could + V1).</text>\n  <text x="380" y="143" font-size="11" fill="#334155">2. Body: Describe challenges faced and</text>\n  <text x="392" y="160" font-size="10.5" fill="#475569">how they succeeded (was able to / managed to).</text>\n  <text x="380" y="183" font-size="11" fill="#334155">3. Conclusion: Present skills, awards and</text>\n  <text x="392" y="200" font-size="10.5" fill="#475569">why their story inspires others today.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
